CREATE TABLE "agent_provider_configs" ("id" TEXT NOT NULL PRIMARY KEY, "provider" TEXT NOT NULL, "name" TEXT NOT NULL, "executable" TEXT NOT NULL, "credential_ref" TEXT, "enabled" BOOLEAN NOT NULL DEFAULT true, "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" DATETIME NOT NULL);
CREATE INDEX "agent_provider_configs_provider_enabled_idx" ON "agent_provider_configs"("provider", "enabled");
CREATE TABLE "agent_profiles" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "provider" TEXT NOT NULL, "provider_config_id" TEXT, "access_level" TEXT NOT NULL DEFAULT 'observe', "workspace_id" TEXT NOT NULL DEFAULT 'default', "model" TEXT, "system_prompt" TEXT NOT NULL DEFAULT '', "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" DATETIME NOT NULL, CONSTRAINT "agent_profiles_provider_config_id_fkey" FOREIGN KEY ("provider_config_id") REFERENCES "agent_provider_configs" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "agent_profiles_workspace_id_provider_idx" ON "agent_profiles"("workspace_id", "provider");
CREATE TABLE "agent_runs" ("id" TEXT NOT NULL PRIMARY KEY, "profile_id" TEXT NOT NULL, "provider" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'queued', "workspace_id" TEXT NOT NULL DEFAULT 'default', "correlation_id" TEXT NOT NULL, "input_json" TEXT NOT NULL DEFAULT '{}', "output_json" TEXT, "usage_json" TEXT, "provider_session_id" TEXT, "error_json" TEXT, "started_at" DATETIME, "finished_at" DATETIME, "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" DATETIME NOT NULL, CONSTRAINT "agent_runs_profile_id_fkey" FOREIGN KEY ("profile_id") REFERENCES "agent_profiles" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "agent_runs_correlation_id_key" ON "agent_runs"("correlation_id");
CREATE INDEX "agent_runs_status_created_at_idx" ON "agent_runs"("status", "created_at");
CREATE INDEX "agent_runs_profile_id_created_at_idx" ON "agent_runs"("profile_id", "created_at");
CREATE TABLE "agent_messages" ("id" TEXT NOT NULL PRIMARY KEY, "run_id" TEXT NOT NULL, "role" TEXT NOT NULL, "content" TEXT NOT NULL, "metadata_json" TEXT NOT NULL DEFAULT '{}', "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "agent_messages_run_id_fkey" FOREIGN KEY ("run_id") REFERENCES "agent_runs" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "agent_messages_run_id_created_at_idx" ON "agent_messages"("run_id", "created_at");
CREATE TABLE "agent_artifacts" ("id" TEXT NOT NULL PRIMARY KEY, "run_id" TEXT NOT NULL, "kind" TEXT NOT NULL, "name" TEXT NOT NULL, "content" TEXT, "path" TEXT, "metadata_json" TEXT NOT NULL DEFAULT '{}', "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "agent_artifacts_run_id_fkey" FOREIGN KEY ("run_id") REFERENCES "agent_runs" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "agent_artifacts_run_id_created_at_idx" ON "agent_artifacts"("run_id", "created_at");
CREATE TABLE "agent_permission_grants" ("id" TEXT NOT NULL PRIMARY KEY, "run_id" TEXT NOT NULL, "capability" TEXT NOT NULL, "resource" TEXT NOT NULL, "decision" TEXT NOT NULL, "decided_by" TEXT NOT NULL, "approval_request_id" TEXT, "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "agent_permission_grants_run_id_fkey" FOREIGN KEY ("run_id") REFERENCES "agent_runs" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "agent_permission_grants_run_id_capability_idx" ON "agent_permission_grants"("run_id", "capability");
